#!/usr/bin/env bash
#
# Check the polynomial identities behind the schoolbook and Montgomery proofs
# with every SMT solver on PATH (z3, cvc5): each identity must be `unsat` (its
# negation has no solution), each negative control `sat`. Exit non-zero
# otherwise.
#
#   crates/ic-ec/proofs/smt/run.sh
#
# A case is `file:answer` for both solvers, or `file:answer:solver` for one:
# `mont-bound.smt2` is nonlinear inequality reasoning that cvc5 1.4.2 does not
# close in five minutes, so it is run on Z3 only. The `mont-*` files are
# generated by `scripts/gen_mont_smt.py 6 crates/ic-ec/proofs/smt`.
#
# See docs/PROOFS.md, "The products" and "P-384 multiplication".

set -uo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
status=0
ran=0
cases="product:unsat square:unsat product-wrong-weight:sat square-undoubled:sat
mont-identity:unsat mont-identity-wrong-weight:sat
mont-rows:unsat mont-rows-without-dropped-words:sat
mont-bound:unsat:z3 mont-bound-unbounded:sat:z3
mont-congruence:unsat"
for solver in z3 cvc5; do
    if ! command -v "$solver" > /dev/null; then
        echo "$solver: not on PATH, skipped"
        continue
    fi
    for case in $cases; do
        IFS=: read -r name want only <<< "$case"
        if [ -n "${only:-}" ] && [ "$only" != "$solver" ]; then
            continue
        fi
        file="$name.smt2"
        start=$(date +%s.%N)
        got=$(timeout 300 "$solver" "$here/$file" 2>&1 | head -n 1)
        end=$(date +%s.%N)
        secs=$(awk -v s="$start" -v e="$end" 'BEGIN { printf "%.2f", e - s }')
        if [ "$got" = "$want" ]; then
            echo "ok   $solver $file: $got (${secs} s)"
        else
            echo "FAIL $solver $file: got '$got', want '$want'"
            status=1
        fi
        ran=$((ran + 1))
    done
done
if [ "$ran" -eq 0 ]; then
    echo "no solver found"
    exit 1
fi
exit $status
